const t={knownGoodPack:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Сохраните снимок рабочей конфигурации принтера как пакет, к которому можно вернуться после неудачной правки."}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Отмена"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Пакетов пока нет. Создайте пакет, пока принтер настроен так, как вам нравится."}},files:{t:0,b:{t:2,i:[{t:3,v:"Файлов конфигурации: "},{t:4,k:"n"}]}},create:{label:{t:0,b:{t:2,i:[{t:3}],s:"Новый пакет"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"напр. Рабочий SV08 - до настройки"}},button:{t:0,b:{t:2,i:[{t:3}],s:"Создать пакет"}}},restore:{button:{t:0,b:{t:2,i:[{t:3}],s:"Восстановить"}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Перезаписать текущую конфигурацию этим пакетом?"}},note:{t:0,b:{t:2,i:[{t:3}],s:"Восстановление перезапишет файлы конфигурации; после этого перезапустите Klipper, чтобы применить изменения."}},restored:{t:0,b:{t:2,i:[{t:3,v:"Восстановлено файлов конфигурации: "},{t:4,k:"count"},{t:3,v:" - перезапустите Klipper, чтобы применить"}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Принтер занят - сейчас восстановить нельзя"}},not_found:{t:0,b:{t:2,i:[{t:3}],s:"Файлы пакета отсутствуют"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"В этом пакете нет файлов"}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:"Не удалось восстановить: "},{t:4,k:"error"}]}}},delete:{button:{t:0,b:{t:2,i:[{t:3}],s:"Удалить"}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Удалить пакет"}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Руководство"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Руководство по пакетам Known-Good"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Закрыть"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Что такое пакет Known-Good?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Снимок всех файлов конфигурации принтера (printer.cfg и подключённых к нему файлов), сохранённый как именованный пакет. Когда принтер печатает хорошо, создайте пакет, чтобы можно было откатиться, если последующая правка что-то сломает."}}},restore:{title:{t:0,b:{t:2,i:[{t:3}],s:"Восстановление пакета"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Восстановление записывает файлы пакета поверх текущей конфигурации. Оно недоступно, пока принтер занят, и после него нужно перезапустить Klipper, чтобы восстановленная конфигурация вступила в силу."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Глоссарий"}}}},glossary:{configPack:{term:{t:0,b:{t:2,i:[{t:3}],s:"Пакет конфигурации"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Сохранённый набор всех файлов конфигурации принтера на определённый момент времени."}}},restorePoint:{term:{t:0,b:{t:2,i:[{t:3}],s:"Точка восстановления"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Заведомо рабочее состояние, к которому можно вернуться - здесь это пакет, созданный, когда принтер работал."}}}}}}};export{t as default};
